  ('sin 18° = (√5 − 1)/4 olduğu bilindiğine göre cos 36° kaçtır?', '(√5 + 1)/4', ['(√5 − 1)/4', '(3 − √5)/4', '(1 + 2√5)/4'], 'cos 36° = 1 − 2sin²18° = 1 − 2(6 − 2√5)/16 = (8 − 6 + 2√5)/8 = (1 + √5)/4.'),
  ('Yarım açı formülünü kullanarak cos 22,5° değerini hesaplayınız.', '√(2 + √2)/2', ['√(2 − √2)/2', '(√2 + 1)/2', '√2/4'], 'cos²22,5° = (1 + cos 45°)/2 = (2 + √2)/4; dar açıda kosinüs pozitif olduğundan √(2 + √2)/2.'),
  ('45°\'nin yarısı olan açının tanjantını yarım açı bağıntısıyla bulursak sonuç ne olur?', '√2 − 1', ['√2 + 1', '1/2', '(2 − √3)/2'], 'tan(θ/2) = (1 − cos θ)/sin θ ile θ = 45°: (1 − √2/2)/(√2/2) = √2 − 1.'),
  ('x ikinci bölgede (90° < x < 180°) ve cos x = −7/25 ise sin(x/2) kaçtır?', '4/5', ['3/5', '−4/5', '16/25'], 'sin²(x/2) = (1 − cos x)/2 = (1 + 7/25)/2 = 16/25. x/2 birinci bölgede olduğundan 4/5.'),
  ('Pay ve paydayı yarım açılara göre yazarak (1 − cos x)/sin x oranını tek terime indirgeyiniz.', 'tan(x/2)', ['cot(x/2)', 'tan x', 'sin(x/2)·cos x'], 'Pay 2sin²(x/2), payda 2 sin(x/2)cos(x/2) olarak yazılınca oran tan(x/2) olur.'),
  ('tan(x/2) = t konumunda sin x hangi ifadeye eşittir?', '2t/(1 + t²)', ['2t/(1 − t²)', '(1 − t²)/(1 + t²)', 't/(1 + t²)'], 'sin x = 2 sin(x/2)cos(x/2) ifadesi cos²(x/2)\'ye bölünüp çarpılırsa 2t/(1 + t²) elde edilir.'),
  ('Yarım açının tanjantı 1/3 olarak veriliyor. Tam açının kosinüsü, t = tan(x/2) dönüşümüyle hesaplanırsa ne bulunur?', '4/5', ['3/5', '8/10 − 1', '2/3'], 'cos x = (1 − t²)/(1 + t²) = (1 − 1/9)/(1 + 1/9) = (8/9)/(10/9) = 4/5.'),
  ('√((1 + cos 40°)/2) ifadesi hangi değere eşittir?', 'cos 20°', ['sin 20°', 'cos 40°', 'cos 20° − sin 20°'], '(1 + cos 2θ)/2 = cos²θ; θ = 20° dar açı olduğundan karekök cos 20° olur.'),
  ('1 + cos x ifadesi çarpım biçiminde aşağıdakilerden hangisine eşittir?', '2cos²(x/2)', ['2sin²(x/2)', 'cos²(x/2)', '2cos(x/2) + 1'], 'cos x = 2cos²(x/2) − 1 olduğundan 1 + cos x = 2cos²(x/2).'),
  ('cos x = 1/2 alarak cos 3x formülünü sınayınız: 4cos³x − 3cos x hangi değeri verir ve bu hangi açının kosinüsüdür?', '−1; 180°\'nin kosinüsü', ['1; 0°\'nin kosinüsü', '0; 90°\'nin kosinüsü', '−1/2; 120°\'nin kosinüsü'], 'x = 60° için 4/8 − 3/2 = −1 olur; gerçekten cos 180° = −1.'),
  ('4 sin 20°·sin 40°·sin 80° çarpımı ile ilgili sin x·sin(60° − x)·sin(60° + x) = (sin 3x)/4 özdeşliği kullanılırsa hangi sonuç bulunur?', '√3/2', ['√3/8', '1/2', '√3/4'], 'x = 20° için çarpım sin 60°/4 = √3/8; 4 ile çarpılınca √3/2 olur.'),
  ('sin a + sin b toplamının çarpım biçimi aşağıdakilerden hangisidir?', '2 sin((a + b)/2)·cos((a − b)/2)', ['2 cos((a + b)/2)·cos((a − b)/2)', '2 sin((a + b)/2)·sin((a − b)/2)', 'sin(a + b)·cos(a − b)'], 'Dönüşüm formülüne göre iki sinüsün toplamı yarım toplamın sinüsüyle yarım farkın kosinüsünün iki katıdır.'),
  ('cos 75° − cos 15° farkının değeri nedir?', '−√2/2', ['√2/2', '−1/2', '−√6/2'], 'cos a − cos b = −2 sin((a + b)/2) sin((a − b)/2) = −2 sin 45° sin 30° = −√2/2.'),
  ('İki kosinüsün çarpımının iki katı, yani 2 cos a·cos b, hangi toplam biçiminde yazılır?', 'cos(a − b) + cos(a + b)', ['cos(a + b) − cos(a − b)', 'sin(a + b) + sin(a − b)', 'cos(a − b) − cos(a + b)'], 'cos(a − b) ve cos(a + b) açılımları toplanınca sinüs çarpımları birbirini götürür ve 2 cos a cos b kalır.'),
  ('Ters dönüşüm formülüne göre 2 sin 75°·cos 15° ifadesi iki sinüsün toplamına açılırsa sonucu ne olur?', '1 + √3/2', ['√3/2', '1/2 + √3/2', '1'], '2 sin a cos b = sin(a + b) + sin(a − b) = sin 90° + sin 60° = 1 + √3/2.'),
  ('2 sin 52,5°·sin 7,5° çarpımının değeri nedir?', '(√2 − 1)/2', ['(√3 − √2)/2', '(√2 + 1)/2', '√2/4'], '2 sin a sin b = cos(a − b) − cos(a + b) = cos 45° − cos 60° = (√2 − 1)/2.'),
  ('Katsayıları 5 ve −12 olan 5 sin x − 12 cos x bileşiminin ulaşabileceği alt sınır nedir?', '−13', ['−17', '−7', '−√119'], 'a sin x + b cos x ifadesi [−√(a² + b²), √(a² + b²)] aralığında değer alır; √(25 + 144) = 13.'),
  ('2 sin x + k cos x = 5 denkleminin gerçek çözümü olması için k² en az kaç olmalıdır?', '21', ['25', '9', '√21'], 'Çözüm için √(4 + k²) ≥ 5 gerekir ⇒ k² ≥ 21.'),
  ('Bir sinyal y = 6 sin x + 8 cos x + 3 bağıntısıyla modelleniyor. Sinyalin aldığı değerlerin oluşturduğu aralık nedir?', '[−7, 13]', ['[−11, 17]', '[−10, 10]', '[3, 13]'], '6 sin x + 8 cos x ifadesi [−10, 10] aralığındadır; 3 eklenince [−7, 13] olur.'),
  ('√3 sin x − cos x = 1 denkleminin [0, 2π) aralığındaki çözümleri hangileridir?', 'π/3 ve π', ['π/6 ve 5π/6', 'π/3 ve 2π/3', '0 ve π'], 'İfade 2 sin(x − π/6) = 1 olur; x − π/6 = π/6 veya 5π/6 ⇒ x = π/3 veya π.'),
  ('a sin x + b cos x biçimindeki bir ifadenin genliği ile a ve b arasındaki ilişki nedir?', '√(a² + b²)', ['a + b', '|a| + |b|', '(a² + b²)/2'], 'İfade √(a² + b²)·sin(x + φ) biçimine getirilebildiğinden genlik √(a² + b²)\'dir.'),
  ('sin x = −1/2 denkleminin [0, 2π) aralığındaki çözüm kümesi hangisidir?', '{7π/6, 11π/6}', ['{π/6, 5π/6}', '{4π/3, 5π/3}', '{−π/6, 7π/6, 11π/6}'], 'Referans açı π/6\'dır; sinüs III. ve IV. bölgelerde negatiftir: π + π/6 ve 2π − π/6.'),
  ('Sinüsün sıfır olduğu noktaların π\'nin katları olduğunu kullanarak sin(3x − π/4) = 0 eşitliğini sağlayan tüm x\'leri yazınız (k tam sayı).', 'x = π/12 + kπ/3', ['x = π/4 + kπ', 'x = π/12 + kπ', 'x = π/12 + 2kπ/3'], '3x − π/4 = kπ ⇒ 3x = π/4 + kπ ⇒ x = π/12 + kπ/3.'),
  ('sin x = 1,2 denkleminin gerçek sayılardaki çözüm kümesi için ne söylenebilir?', 'Boş kümedir', ['Tek elemanlıdır', 'Sonsuz elemanlıdır', 'İki elemanlıdır'], 'Sinüs fonksiyonu yalnız [−1, 1] aralığında değer aldığından 1,2 değerine hiç ulaşmaz.'),
  ('Çarpanlara ayırma yoluyla sin x = sin 2x eşitliğini 0 ile π arasında (uçlar dahil) çözünüz.', '0, π/3 ve π', ['0 ve π', 'π/3 ve 2π/3', '0, π/2 ve π'], 'sin 2x − sin x = sin x(2cos x − 1) = 0 ⇒ sin x = 0 (0, π) veya cos x = 1/2 (π/3).'),
  ('cos x = −√3/2 denkleminin [0°, 360°) aralığındaki kökleri hangileridir?', '150° ve 210°', ['30° ve 330°', '120° ve 240°', '150° ve 330°'], 'Referans açı 30°\'dir; kosinüs II. ve III. bölgede negatiftir: 180 − 30 ve 180 + 30.'),
  ('cos x = a denkleminin bir kökü α ise genel çözüm nasıl ifade edilir (k ∈ ℤ)?', 'x = ±α + 2kπ', ['x = α + kπ', 'x = π − α + 2kπ', 'x = ±α + kπ'], 'Kosinüs çift fonksiyon olduğundan α ve −α aynı kosinüs değerini verir; periyot 2π\'dir.'),
  ('tan x = a denkleminin genel çözümü, bir çözüm α ise neden x = α + kπ biçimindedir?', 'Tanjantın periyodu π olduğu için', ['Tanjant çift fonksiyon olduğu için', 'Tanjant [−1, 1] aralığında olduğu için', 'Tanjantın periyodu 2π olduğu için'], 'tan(x + π) = tan x olduğundan her π aralıkta aynı değer tekrarlanır; başka çözüm yoktur.'),
  ('cos 2x = cos x denkleminin [0, 2π) aralığında kaç çözümü vardır?', '3', ['2', '4', 'Sonsuz'], '2cos²x − cos x − 1 = 0 ⇒ cos x = 1 (x = 0) veya cos x = −1/2 (2π/3, 4π/3); toplam 3.'),
  ('tan 2x = tan(x + π/6) denkleminin genel çözümü nedir (k ∈ ℤ)?', 'x = π/6 + kπ', ['x = π/6 + 2kπ', 'x = π/12 + kπ/2', 'x = kπ'], 'Tanjantları eşit açılar π\'nin katı kadar farklıdır: 2x − x − π/6 = kπ.'),
  ('cot x = √3 denkleminin (0, π) aralığındaki çözümü nedir?', 'π/6', ['π/3', '5π/6', '2π/3'], 'Kotanjant bu aralıkta azalandır ve cot(π/6) = √3\'tür; tek çözüm π/6.'),
  ('2sin²x − 3 sin x + 1 = 0 eşitliğini sağlayan sin x değerleri hangileridir?', '1/2 ve 1', ['−1/2 ve 1', '1/2 ve −1', '1 ve 2'], 't = sin x için 2t² − 3t + 1 = (2t − 1)(t − 1) = 0 ⇒ t = 1/2 veya t = 1.'),
  ('Kosinüse göre ikinci dereceden 2cos²x + cos x − 1 = 0 eşitliği, bir tam tur içinde (0 dahil, 2π hariç) kaç açı tarafından sağlanır?', '3', ['2', '4', '5'], '(2cos x − 1)(cos x + 1) = 0 ⇒ cos x = 1/2 (π/3, 5π/3) veya cos x = −1 (π); üç kök.'),
  ('2sin²x + 3cos x = 3 denklemi cos x türünden ikinci dereceye getirilirse cos x hangi değerleri alabilir?', '1 ve 1/2', ['−1 ve 1/2', '1 ve −1/2', '2 ve 1'], '2(1 − cos²x) + 3cos x − 3 = 0 ⇒ 2cos²x − 3cos x + 1 = 0 ⇒ cos x = 1 veya 1/2.'),
  ('cos 2x + sin x = 0 denkleminde sin x değerleri hangileridir?', '1 ve −1/2', ['−1 ve 1/2', '1/2 ve 1', '−1 ve −1/2'], '1 − 2sin²x + sin x = 0 ⇒ 2sin²x − sin x − 1 = 0 ⇒ (2 sin x + 1)(sin x − 1) = 0.'),
  ('sin x·cos x = 0 denkleminin [0, 2π) aralığındaki tüm kökleri kaç tanedir?', '4', ['2', '3', '6'], 'sin x = 0 ⇒ 0, π; cos x = 0 ⇒ π/2, 3π/2. Toplam dört kök vardır.'),
  ('3tan²x − 4√3 tan x + 3 = 0 denkleminin dar açı olan çözümleri hangileridir?', '30° ve 60°', ['45° ve 60°', '30° ve 45°', '60° ve 75°'], 'tan x = t için 3t² − 4√3t + 3 = 0 ⇒ t = √3 veya t = 1/√3 ⇒ 60° veya 30°.'),
  ('Sinüs değeri 0,3 olan açılar, iki tam turluk [0, 4π] aralığında kaç kez ortaya çıkar?', '4', ['2', '3', '8'], 'Her 2π uzunluğundaki periyotta sinüs 0,3 değerini iki kez alır; iki periyotta dört kök vardır.'),
  ('Üç katının kosinüsü 1 olan x açıları, uçları dahil 0 ile 2π arasında kaç tanedir?', '4', ['3', '6', '2'], '3x = 2kπ ⇒ x = 2kπ/3; aralıktaki değerler 0, 2π/3, 4π/3 ve 2π\'dir.'),
  ('sin 4x = 1/2 denkleminin [0, π) aralığındaki çözüm sayısı kaçtır?', '4', ['2', '8', '6'], '4x ∈ [0, 4π) aralığında sinüs 1/2 değerini her periyotta iki kez alır; iki periyotta 4 kez.'),
  ('Tanjantı 5 olan açıların, 0 ile 10π arasındaki açık aralıkta kaç tane bulunduğunu periyottan yararlanarak belirleyiniz.', '10', ['5', '20', '11'], 'Tanjantın periyodu π olup her π uzunluğundaki aralıkta bir kez 5 değerini alır; 10 aralık vardır.'),
  ('cos x = −1 denkleminin kapalı [−3π, 3π] aralığındaki kök sayısı kaçtır?', '4', ['3', '2', '6'], 'Kökler π\'nin tek katlarıdır: −3π, −π, π ve 3π; uçlar dahil olduğundan dört kök vardır.'),
  ('Mutlak değerli |sin x| = 1/2 eşitliği bir tam tur boyunca kaç farklı açıda sağlanır?', '4', ['2', '6', '8'], 'sin x = 1/2 ⇒ π/6, 5π/6; sin x = −1/2 ⇒ 7π/6, 11π/6. Toplam dört kök.'),
  ('Bir dalga y = sin(πt/2) ile modelleniyor (t saniye). İlk 10 saniyede (0 < t ≤ 10) dalganın en yüksek değere kaç kez ulaştığını bulunuz.', '3', ['5', '2', '10'], 'πt/2 = π/2 + 2kπ ⇒ t = 1 + 4k; uygun değerler t = 1, 5, 9 olup üç kezdir.'),
  ('Bir gözlemci A noktasından bir kuleye bakarken kule yönü ile AB doğrultusu 70°, B noktasından bakarken BA doğrultusu ile kule yönü 50° açı yapıyor. |AB| = 100 m ise kulenin A\'ya uzaklığını veren ifade hangisidir?', '100·sin 50°/sin 60°', ['100·sin 70°/sin 60°', '100·sin 60°/sin 50°', '100·cos 50°/cos 60°'], 'Üçgenin üçüncü açısı 180 − 70 − 50 = 60°\'dir. A\'ya olan uzaklık B\'deki 50°\'lik açının karşısındadır: d = 100·sin 50°/sin 60°.'),
  ('Kenarları 4, 5 ve 7 olan bir üçgenin en büyük açısı için hangi sınıflandırma doğrudur?', 'Geniş açıdır', ['Dik açıdır', 'Dar açıdır', 'Tam olarak 60°\'dir'], '7² = 49 > 4² + 5² = 41 olduğundan en büyük açının kosinüsü negatiftir; açı geniştir.'),
  ('Bir paralelkenarın kenarları 6 ve 10 cm, aralarındaki açı 60°\'dir. Kısa köşegeni kaç cm\'dir?', '2√19', ['14', '2√34', '4√19'], 'Kısa köşegen dar açının karşısındadır: d² = 36 + 100 − 2·6·10·(1/2) = 76 ⇒ d = 2√19.'),
  ('Kenarları 6 ve 10 cm, aralarındaki dar açısı 60° olan paralelkenarın uzun köşegeni kaç cm\'dir?', '14', ['2√19', '16', '2√34'], 'Uzun köşegen 120°\'lik açının karşısındadır: d² = 36 + 100 + 60 = 196 ⇒ d = 14 cm.'),
  ('Genişletilmiş sinüs teoremine göre a/sin A oranı, üçgenin çevrel çemberinin yarıçapı R ile nasıl ilişkilidir?', '2R\'ye eşittir', ['R\'ye eşittir', 'R/2\'ye eşittir', 'πR\'ye eşittir'], 'Çevrel çemberde çap çizilip çevre açı özelliği kullanılırsa a = 2R·sin A elde edilir.'),
  ('Bir kulenin tepesine, kuleye doğru 20 m yaklaşan bir gözlemcinin yükselme açısı 30°\'den 60°\'ye çıkıyor. Kulenin yüksekliği kaç metredir?', '10√3', ['20√3', '10√3/3', '20'], 'h = x·tan 60° = (x + 20)·tan 30° ⇒ 3x = x + 20 ⇒ x = 10 ve h = 10√3 m.'),
  ('A noktasından B\'ye bakışın yükselme açısı 25° ise, B noktasından A\'ya bakışın alçalma açısı kaç derecedir?', '25°', ['65°', '155°', '115°'], 'Yatay doğrultular birbirine paraleldir; ters açılar iç ters açı olduğundan alçalma açısı da 25°\'dir.'),
  ('Bir uçak 1500 m yükseklikte uçarken pilot, havaalanı pistinin başlangıcını 30°\'lik alçalma açısıyla görüyor. Uçağın piste olan yatay uzaklığı yaklaşık kaç metredir? (√3 ≈ 1,73)', '2595', ['866', '3000', '1500'], 'd = 1500/tan 30° = 1500√3 ≈ 2595 m.'),
  ('Bir nehrin karşı kıyısındaki ağacı, bulunduğu yerden tam karşıda gören bir öğrenci kıyı boyunca 50 m yürüyor; artık ağaca bakış doğrultusu kıyıyla 60° açı yapıyor. Nehrin genişliği kaç metredir?', '50√3', ['25', '50√3/3', '100'], 'Genişlik/50 = tan 60° ⇒ genişlik = 50√3 m.'),
  ('Eğimi %10 olan bir yokuşta (yatayda 100 m\'de 10 m yükseliş) yolun yatayla yaptığı açının tanjantı kaçtır?', '0,1', ['10', '0,01', '1'], 'Eğim yüzdesi yükselişin yatay uzaklığa oranıdır; tan α = 10/100 = 0,1.'),
  ('(sec x − cos x)/tan x ifadesi neye eşittir?', 'sin x', ['cos x', 'tan x', 'sec x·sin x'], 'sec x − cos x = (1 − cos²x)/cos x = sin²x/cos x; tan x\'e bölünce sin x kalır.'),
  ('cos x/(1 − sin x) − cos x/(1 + sin x) farkını sadeleştiriniz.', '2 tan x', ['2 sec x', '0', '2 sin x'], 'Ortak payda 1 − sin²x = cos²x; pay 2 sin x cos x olur ve sonuç 2 sin x/cos x = 2 tan x.'),
  ('Sekant ve kosekant karelerini kullanarak (1 + tan²x)·cos²x + (1 + cot²x)·sin²x toplamını sadeleştirin.', '2', ['1', 'sec²x + csc²x', '0'], 'Her parantez sırasıyla 1/cos²x ve 1/sin²x olduğundan çarpımlar 1 + 1 = 2 eder.'),
  ('(1 − sin x)/cos x ifadesine özdeş olan hangisidir?', 'cos x/(1 + sin x)', ['cos x/(1 − sin x)', '(1 + sin x)/cos x', 'sin x/(1 + cos x)'], 'Pay ve payda (1 + sin x) ile genişletilirse pay 1 − sin²x = cos²x olur; sadeleşince cos x/(1 + sin x).'),
  ('cot x − tan x ifadesi hangi tek terime eşittir?', '2 cot 2x', ['cot 2x', '2 tan 2x', 'cos 2x'], '(cos²x − sin²x)/(sin x cos x) = cos 2x/((sin 2x)/2) = 2 cot 2x.'),
  ('1/(1 − sin x) + 1/(1 + sin x) toplamı aşağıdakilerden hangisine özdeştir?', '2 sec²x', ['2 csc²x', '2', 'sec²x + 1'], 'Ortak payda 1 − sin²x = cos²x, pay 2 olduğundan sonuç 2/cos²x = 2 sec²x.'),
  ('tan 20°·tan 40°·tan 80° çarpımının değeri nedir?', '√3', ['1', '√3/3', '3'], 'tan x·tan(60° − x)·tan(60° + x) = tan 3x özdeşliğinde x = 20° alınırsa tan 60° = √3.'),
  ('72° ve 144° açılarının kosinüsleri toplandığında, yani cos(2π/5) + cos(4π/5) hesaplandığında elde edilen sayı nedir?', '−1/2', ['1/2', '0', '−√5/4'], 'cos 72° = (√5 − 1)/4 ve cos 144° = −(√5 + 1)/4; toplam −2/4 = −1/2.'),
  ('ABC üçgeninde cos A = 4/5 ve cos B = 5/13 ise cos C değeri nedir?', '16/65', ['56/65', '−16/65', '33/65'], 'sin A = 3/5, sin B = 12/13; cos C = −cos(A + B) = −(20/65 − 36/65) = 16/65.'),
  ('Bir tam tur içinde sinüs değerinin 1/2\'yi aştığı açılar hangi açık aralığı oluşturur?', '(π/6, 5π/6)', ['(π/3, 2π/3)', '(0, π/6)', '(5π/6, 2π)'], 'Sinüs π/6 ile 5π/6 arasında 1/2\'nin üzerindedir; bu iki noktada tam 1/2\'ye eşittir.'),
  ('cos x ≤ 0 koşulunu sağlayan [0, 2π) aralığındaki x değerleri hangi aralıktadır?', '[π/2, 3π/2]', ['[0, π]', '(π/2, 3π/2)', '[π, 2π)'], 'Kosinüs II. ve III. bölgelerde negatif, π/2 ve 3π/2\'de sıfırdır; eşitlik dahil olduğundan uçlar alınır.'),
  ('tan x < 1 eşitsizliğinin (−π/2, π/2) aralığındaki çözümü nedir?', '(−π/2, π/4)', ['(π/4, π/2)', '(−π/4, π/4)', '(0, π/4)'], 'Tanjant bu aralıkta artandır ve tan(π/4) = 1; dolayısıyla x < π/4 olmalıdır.'),
  ('2cos x + √3 < 0 eşitsizliğinin [0, 2π) içindeki çözüm aralığı hangisidir?', '(5π/6, 7π/6)', ['(π/6, 11π/6)', '(2π/3, 4π/3)', '(7π/6, 11π/6)'], 'cos x < −√3/2 olmalıdır; bu durum 5π/6 ile 7π/6 arasında gerçekleşir.'),
  ('|cos x| < 1/2 eşitsizliğini sağlayan açıların [0, π] içindeki kısmı hangisidir?', '(π/3, 2π/3)', ['(0, π/3)', '(π/6, 5π/6)', '(2π/3, π]'], '−1/2 < cos x < 1/2 olmalıdır; [0, π] aralığında bu π/3 < x < 2π/3 demektir.'),
  ('Her gerçek x için 3 + sin x > 0 eşitsizliği neden doğrudur?', 'sin x en az −1 olabildiği için', ['sin x her zaman pozitif olduğu için', 'sin x\'in periyodu 2π olduğu için', 'sin x en çok 3 olabildiği için'], 'sin x ≥ −1 ⇒ 3 + sin x ≥ 2 > 0 olduğundan eşitsizlik her x için sağlanır.'),
  ('Radyan cinsinden çok küçük x açıları için sin x için yaygın olarak kullanılan yaklaşım hangisidir?', 'sin x ≈ x', ['sin x ≈ 1', 'sin x ≈ x²', 'sin x ≈ 1 − x'], 'Sıfıra yakın açılarda sinüs eğrisi y = x doğrusuna çok yakındır; fizikte sarkaç problemlerinde bu yaklaşım kullanılır.'),
  ('Çok küçük x (radyan) değerleri için cos x için kullanılan ikinci dereceden yaklaşım hangisidir?', 'cos x ≈ 1 − x²/2', ['cos x ≈ x', 'cos x ≈ 1 + x²/2', 'cos x ≈ 1 − x'], 'Kosinüs sıfır civarında 1\'e yakındır ve parabolik biçimde azalır; Maclaurin açılımının ilk iki terimi 1 − x²/2\'dir.'),
  ('sin 1° değeri, 1°\'nin radyan karşılığı kullanılarak yaklaşık kaç bulunur?', '0,0175', ['0,1745', '0,01', '0,0349'], '1° = π/180 ≈ 0,01745 radyan; küçük açılarda sin x ≈ x olduğundan sin 1° ≈ 0,0175.'),
  ('Yarıçapı 20 m olan bir dönme dolabın merkezi yerden 22 m yüksektedir. Bir kabinin yerden yüksekliği alabileceği en büyük değer kaç metredir?', '42', ['40', '22', '44'], 'En yüksek nokta merkezin 20 m üzerindedir: 22 + 20 = 42 m.'),
  ('Bir yaydaki cismin konumu x(t) = 4 sin(2t) cm ile veriliyor. Cismin denge konumundan en çok kaç cm uzaklaşır?', '4', ['8', '2', '2π'], 'Sinüsün en büyük mutlak değeri 1 olduğundan uzaklaşma en çok genliğe, yani 4 cm\'ye eşittir.'),
  ('Bir şehirde günlük ortalama sıcaklık T(n) = 12 + 10 sin(2π(n − 105)/365) °C ile modelleniyor (n yılın günü). Yıl içindeki en yüksek ve en düşük ortalama sıcaklık arasındaki fark kaç °C\'dir?', '20', ['10', '12', '22'], 'Sinüs −1 ile 1 arasında değiştiğinden sıcaklık 2 ile 22 °C arasındadır; fark 20 °C.'),
  ('Kutupsal koordinatlarda θ = π/4 denklemi (r her gerçek değeri alabilirse) hangi geometrik şekli belirtir?', 'y = x doğrusu', ['Yarıçapı π/4 olan çember', 'y = −x doğrusu', 'x ekseni'], 'Orijinden 45° eğimle geçen bütün noktalar tan θ = y/x = 1 koşulunu sağlar; bu y = x doğrusudur.'),
  ('Bilinen ilk kiriş tablosunu hazırladığı için sıklıkla "trigonometrinin babası" olarak anılan Antik Yunan gökbilimcisi kimdir?', 'Hipparkos', ['Öklid', 'Pisagor', 'Eratosthenes'], 'MÖ 2. yüzyılda yaşayan Hipparkos, gökbilim hesapları için çemberde kiriş uzunluklarını tablolaştırmıştır.'),
  ('Ptolemaios\'un kiriş tablosunu da içeren ve yüzyıllarca gökbilimin temel kaynağı olan eseri hangi adla bilinir?', 'Almagest', ['Elementler', 'Konikler', 'Aritmetika'], 'Ptolemaios\'un MS 2. yüzyılda yazdığı Mathematike Syntaxis, Arapça çevirisinden gelen Almagest adıyla tanınır.'),
  ('Latince "sinus" sözcüğünün trigonometride kullanılmaya başlanması hangi süreçle açıklanır?', 'Arapça bir sözcüğün \'cep\' anlamıyla okunup çevrilmesi', ['Bir Roma mühendisinin kemer yapımında kullandığı terim olması', 'Yunanca \'eğri\' sözcüğünün doğrudan alınması', 'Sinüs eğrisinin dalgaya benzemesi nedeniyle uydurulması'], 'Sanskritçe jya (kiriş) Arapçaya jiba olarak geçmiş; ünlüsüz yazımı jayb (\'koyun, cep\') diye okununca Latinceye sinus olarak çevrilmiştir.'),
  ('Tanjant ve kotanjant kavramlarının tarihsel kökeni hangi gözlemle ilişkilidir?', 'Dikilen bir çubuğun gölge uzunluğu', ['Gemilerin pusula sapmaları', 'Kum saatindeki akış hızı', 'Ay\'ın evreleri arasında geçen gün sayısı'], 'İslam dünyası gökbilimcileri, düşey ve yatay çubukların (gnomon) gölge uzunluklarını açıya bağlı olarak tablolaştırmıştır; bu tablolar tanjant ve kotanjant değerlerine karşılık gelir.'),
  ('1464 dolaylarında yazılan "De triangulis omnimodis" eseriyle Avrupa\'da trigonometriyi bağımsız bir dal olarak sunan matematikçi kimdir?', 'Regiomontanus', ['Nikolaus Kopernikus', 'Fibonacci', 'Kepler'], 'Johannes Müller (Regiomontanus) bu eserinde düzlem ve küresel üçgenlerin çözümünü sistemli biçimde anlatmıştır.'),
  ('Eratosthenes, Siene ile İskenderiye arasındaki güneş ışını farkını tam çemberin 1/50\'si olarak ölçmüştür. Bu açı kaç derecedir?', '7,2°', ['12,5°', '3,6°', '50°'], '360°/50 = 7,2° bulunur; iki kent arası uzaklık 50 ile çarpılarak Dünya\'nın çevresi hesaplanmıştır.'),
  ('Fransa\'da kosinüs teoremine kimin adı verilir?', 'Cemşid el-Kâşî', ['Blaise Pascal', 'René Descartes', 'Pierre-Simon Laplace'], 'El-Kâşî, kosinüs teoremini trigonometrik biçimde açıkça ifade edip kullandığı için Fransızcada théorème d\'Al-Kashi adı kullanılır.'),
  ('Trigonometrik oranları üçgen kenarlarının oranı olmaktan çıkarıp sayılar üzerinde tanımlı fonksiyonlar olarak inceleyen ve sin, cos gösterimlerini yaygınlaştıran 18. yüzyıl matematikçisi kimdir?', 'Leonhard Euler', ['Isaac Newton', 'Carl Friedrich Gauss', 'Pierre de Fermat'], 'Euler, 1748 tarihli Introductio in analysin infinitorum eserinde trigonometrik fonksiyonları birim çember üzerinde sistemli biçimde tanımlamıştır.'),
  ('Bir ikizkenar üçgende eşit kenarlar 10 cm, taban 12 cm\'dir. Taban açılarından birinin kosinüsü kaçtır?', '3/5', ['4/5', '6/10·2', '3/4'], 'Tepeden tabana inen yükseklik tabanı 6\'şar cm\'ye böler; cos = 6/10 = 3/5.'),
  ('Dik üçgende dar açılardan biri büyüdükçe o açının kosinüsü ve tanjantı nasıl değişir?', 'Kosinüs azalır, tanjant artar', ['İkisi de aynı oranda artar', 'İkisi de azalır', 'Kosinüs artar, tanjant azalır'], 'Açı büyüdükçe komşu kenarın hipotenüse oranı küçülür, karşı kenarın komşu kenara oranı büyür.'),
  ('Bir dik üçgende hipotenüs 10 cm ve bir dar açı α\'dır. Dik kenarların toplamını α cinsinden veren ifade hangisidir?', '10(sin α + cos α)', ['10·sin α·cos α', '10(tan α + cot α)', '5(sin α + cos α)'], 'Dik kenarlar 10 sin α ve 10 cos α\'dır; toplamları 10(sin α + cos α).'),
  ('Hipotenüsü 10 cm, bir dar açısı α olan dik üçgenin alanı sin 2α cinsinden nasıl yazılır?', '25 sin 2α', ['50 sin 2α', '25 sin α·cos α', '10 sin 2α'], 'Alan = (1/2)(10 sin α)(10 cos α) = 50 sin α cos α = 25 sin 2α.'),
  ('Kenarı 4 birim olan bir küpte bir yüzün köşegeni ile cismin köşegeni arasındaki açının kosinüsü kaçtır?', '√6/3', ['√3/3', '√2/2', '2/3'], 'Yüz köşegeni 4√2, cisim köşegeni 4√3 olup bunlar dik üçgen oluşturur: cos = 4√2/(4√3) = √6/3.'),
  ('Düzgün altıgenin kenarı 4 cm\'dir. Karşılıklı paralel iki kenarı arasındaki uzaklık kaç cm\'dir?', '4√3', ['8', '2√3', '8√3'], 'Altıgen altı eşkenar üçgenden oluşur; paralel kenarlar arası uzaklık iki üçgen yüksekliği 2·(4√3/2) = 4√3 cm.'),
  ('İkizkenar dik üçgende hipotenüse ait yükseklik hipotenüsün kaçta kaçıdır?', '1/2', ['√2/2', '1/√3', '1/4'], 'Yükseklik hipotenüsü iki eş parçaya böler ve her parça yüksekliğe eşittir; h = hipotenüs/2.'),
  ('Kenarı 2 cm olan ABCD karesinde A köşesinden CD kenarının orta noktası M\'ye bir doğru parçası çiziliyor. AM ile AD kenarı arasındaki açının tanjantı kaçtır?', '1/2', ['2', '√5/5', '1'], 'D köşesinde dik açı olan ADM üçgeninde |AD| = 2 ve |DM| = 1\'dir; A\'daki açı için tan = |DM|/|AD| = 1/2.'),
  ('Birim çember üzerindeki bir noktanın koordinatlarının karelerinin toplamı neden her zaman 1\'dir?', 'Nokta orijine 1 birim uzaklıktadır', ['Koordinatlar her zaman pozitif değer alır', 'Açı hep 90°\'dir', 'Tanjant hep 1\'dir'], 'Uzaklık formülüne göre x² + y² = 1² olduğundan cos²θ + sin²θ = 1 bağıntısı buradan çıkar.'),
  ('Birim çemberde 30° ve 150°\'lik açılara karşılık gelen iki nokta arasındaki uzaklık kaç birimdir?', '√3', ['1', '2', '√2'], 'Noktalar (√3/2, 1/2) ve (−√3/2, 1/2)\'dir; aralarındaki uzaklık √3.'),
  ('İkinci bölgedeki üç açı için sin 120°, cos 150° ve tan 135° değerleri toplanırsa hangi sayı bulunur?', '−1', ['1', '√3 − 1', '0'], 'sin 120° = √3/2, cos 150° = −√3/2, tan 135° = −1; toplam −1.'),
  ('(tan 60° − tan 30°)/(1 + tan 60°·tan 30°) ifadesinin değeri kaçtır?', '√3/3', ['√3', '1', '√3/2 − 1'], 'Bu ifade tan(60° − 30°) = tan 30° = √3/3\'tür; doğrudan hesap da (√3 − √3/3)/2 = √3/3 verir.'),
  ('3 sin x = 4 cos x eşitliğini sağlayan dar açı x için sin x + cos x toplamı kaçtır?', '7/5', ['1', '5/7', '12/5'], 'tan x = 4/3 ⇒ 3-4-5 üçgeni; sin x = 4/5, cos x = 3/5; toplam 7/5.'),
  ('(sin x + 2 cos x)/(sin x − cos x) oranı 4\'e eşittir. Pay ve paydayı cos x\'e bölerek tanjantı bulunuz.', '2', ['1/2', '3', '−2'], 'Pay ve payda cos x\'e bölünür: (t + 2)/(t − 1) = 4 ⇒ t + 2 = 4t − 4 ⇒ t = 2.'),
  ('tan x = 3 olduğuna göre sin²x − sin x·cos x ifadesinin değeri kaçtır?', '3/5', ['6/10 + 1', '9/10', '1/5'], 'İfade cos²x ile çarpılıp bölünür: (tan²x − tan x)/(1 + tan²x) = (9 − 3)/10 = 3/5.'),
  ('y = cos x eğrisi ile y = 1/2 doğrusu [0, 2π] aralığında hangi apsislerde kesişir?', 'π/3 ve 5π/3', ['π/6 ve 11π/6', 'π/3 ve 2π/3', '2π/3 ve 4π/3'], 'cos x = 1/2 eşitliği bu aralıkta x = π/3 ve x = 2π − π/3 için sağlanır.'),
  ('y = cos 2x fonksiyonunun grafiği y = cos x grafiğine göre nasıl değişir?', 'Yatay doğrultuda yarıya sıkışır', ['Dikey doğrultuda iki kat uzar', 'Yatay doğrultuda iki kat genişler', 'Yukarı doğru 2 birim kayar'], 'x yerine 2x yazılması periyodu 2π\'den π\'ye indirir; grafik yatayda sıkışır, genlik değişmez.'),
  ('y = 3 − 2 sin(x/2) fonksiyonunun en küçük değeri ile periyodunun toplamı kaçtır?', '1 + 4π', ['5 + 4π', '1 + π', '3 + 2π'], 'En küçük değer 3 − 2 = 1, periyot 2π/(1/2) = 4π; toplam 1 + 4π.'),
  ('cos²x − sin²x = 1/2 denklemini sağlayan (0, π/2) aralığındaki x nedir?', 'π/6', ['π/3', 'π/4', 'π/12'], 'İfade cos 2x\'tir; cos 2x = 1/2 ve 2x ∈ (0, π) ⇒ 2x = π/3 ⇒ x = π/6.'),
  ('Ortak çarpan parantezine alınarak çözülen 2sin²x + sin x = 0 eşitliği, bir tam turda kaç açı için doğrudur?', '4', ['2', '3', '5'], 'sin x(2 sin x + 1) = 0 ⇒ sin x = 0 (0, π) veya sin x = −1/2 (7π/6, 11π/6); toplam dört.'),
  ('f(x) = sin x − cos x fonksiyonu en büyük değerini [0, 2π) aralığında hangi x için alır?', '3π/4', ['π/4', '5π/4', '−π/4'], 'sin x − cos x = √2 sin(x − π/4); en büyük değer x − π/4 = π/2 ⇒ x = 3π/4 için √2\'dir.'),
  ('Dünya kendi ekseni etrafında 24 saatte bir tur döndüğüne göre açısal hızı saatte kaç radyandır?', 'π/12', ['π/720', '2π', 'π/6'], '2π/24 = π/12 radyan/saat; bu, saatte 15°\'lik dönmeye karşılık gelir.'),
  ('Askeri ve topçuluk uygulamalarında kullanılan, tam açıyı 6400 eşit parçaya bölen birim hangisidir?', 'Milyem (mil)', ['Grad', 'Gon', 'Yay dakikası (arkdakika)'], 'NATO milyemi tam açıyı 6400 parçaya böler; 1 milyem yaklaşık 1 km\'de 1 m\'lik sapmaya karşılık gelir.'),
  ('Yarıçapı 6 cm olan bir çembere çizilen düzgün sekizgenin alanı kaç cm²\'dir?', '72√2', ['144', '36√2', '144√2'], 'Sekizgen merkezde 45°\'lik 8 üçgene ayrılır: 8·(1/2)·6·6·sin 45° = 144·(√2/2) = 72√2.'),
  ('Yarıçapı r olan çembere içten çizilmiş düzgün n-genin alanı hangi formülle verilir?', '(n/2)·r²·sin(2π/n)', ['n·r²·sin(2π/n)', '(n/2)·r²·sin(π/n)', '(n/2)·r²·cos(2π/n)'], 'Merkezde 2π/n açılı n eş ikizkenar üçgen oluşur; her birinin alanı (1/2)r² sin(2π/n).'),
  ('Bir deniz fenerinden bakan bir gözcü, bir gemiyi önce kuzey yönünde 4 km uzakta, bir saat sonra doğu yönünde 3 km uzakta görüyor. Gemi bu sürede en az kaç km yol almıştır?', '5', ['7', '1', '√7'], 'İki konum arası uzaklık dik üçgen hipotenüsüdür: √(16 + 9) = 5 km.'),
  ('Bir öğrenci sin(a + b) = sin a + sin b yazıyor. Bu iddiayı çürütmek için en uygun karşı örnek hangisidir?', 'a = b = 45°: sol yan 1, sağ yan √2', ['a = b = 0° alınca iki yan eşit olur', 'a = 30°, b = 0° alınca iki yan eşit olur', 'a = 90°, b = 0° alınca iki yan 1 olur'], 'Karşı örnek eşitliği bozan bir durum olmalıdır; sin 90° = 1 iken sin 45° + sin 45° = √2\'dir. Diğer seçeneklerde eşitlik tesadüfen sağlanır.'),
  ('"sin 2x = 2 sin x" eşitliği için hangi değerlendirme doğrudur?', 'Yalnız sin x = 0 iken doğrudur', ['Her x için doğru bir özdeşliktir', 'Hiçbir x için doğru değildir', 'Yalnız x = 45° için doğrudur'], '2 sin x cos x = 2 sin x ⇒ sin x(cos x − 1) = 0 ⇒ sin x = 0 (cos x = 1 durumu da sin x = 0\'ı gerektirir).'),
  ('Bir öğrenci sin x = 1/2 denklemini çözerken yalnız x = 30° yazıyor. Çözümün [0°, 360°) aralığındaki eksiği nedir?', '150° çözümünü atlamıştır', ['210° çözümünü atlamıştır', '330° çözümünü atlamıştır', 'Eksiği yoktur, çözüm tamdır'], 'Sinüs I. ve II. bölgelerde pozitiftir; 180° − 30° = 150° de bir çözümdür.'),
  ('Bir öğrenci hesap makinesinde sin 30 tuşladığında −0,988 sonucunu görüyor. Bunun en olası nedeni nedir?', 'Makine radyan kipindedir', ['Hesap makinesi bozuktur', 'Hesap makinesi grad kipindedir', '30 sayısı negatif girilmiştir'], '30 radyanın sinüsü yaklaşık −0,988\'dir; derece kipinde sonuç 0,5 olurdu.'),
  ('cos x = 2 eşitliğini sağlayan bir x açısı bulduğunu söyleyen birine ne yanıt verilmelidir?', 'Böyle bir gerçek açı yoktur', ['x = 0 için sağlanır', 'x = 2π için sağlanır', 'x = 60°\'nin iki katı için sağlanır'], 'Kosinüs fonksiyonu gerçek x için yalnız [−1, 1] aralığında değer alır.'),
  ('Aşağıdaki eşitliklerden hangisi bir özdeşlik değildir (her x için doğru değildir)?', 'sin x + cos x = 1', ['sin²x + cos²x = 1', 'sin(−x) = −sin x', 'cos(2π + x) = cos x'], 'sin x + cos x = 1 yalnız bazı açılarda (ör. x = 0) doğrudur; x = 45°\'de değer √2 olur.'),
  ('"Bir açının sinüsü 0,5 ise o açı 30°\'dir" ifadesi için hangi değerlendirme doğrudur?', 'Yanlıştır; örneğin 150° de aynı sinüsü verir', ['Doğrudur; sinüs bire birdir', 'Yalnız radyan kullanılırsa doğrudur', 'Yanlıştır; sinüsü 0,5 olan açı 60°\'dir'], 'Sinüs fonksiyonu bire bir olmadığından aynı değer sonsuz çoklukta açıda alınır.'),
  ('Bir dik üçgende bir dar açının sinüsü ile kosinüsünün toplamının 1\'den küçük olamayacağının nedeni nedir?', 'İki dik kenarın toplamı hipotenüsü aşar', ['Sinüs ve kosinüs her dar açıda birbirine eşittir', 'Hipotenüs her zaman 1\'dir', 'Tanjant 1\'den büyüktür'], '(a + b)/c > 1 olur çünkü üçgen eşitsizliğine göre iki kenarın toplamı üçüncüden büyüktür.'),
  ('Kosinüs teoremi ile sinüs teoremi arasında seçim yaparken iki kenar ve aradaki açı verilmişse hangisiyle başlamak uygundur?', 'a² = b² + c² − 2bc·cos A bağıntısı', ['Sinüs teoremi', 'Pisagor teoremi', 'Tanjant teoremi ve açıortay bağıntısı'], 'İki kenar ve aradaki açı (KAK) durumunda bilinmeyen üçüncü kenar doğrudan kosinüs teoremiyle bulunur.'),
  ('İki açı ve bir kenarı bilinen bir üçgende diğer kenarları bulmak için en uygun araç hangisidir?', 'Sinüs teoremi', ['Kosinüs teoremi', 'Heron formülü', 'Pisagor teoremi'], 'Üçüncü açı 180°\'den bulunur; ardından kenarlar karşı açıların sinüsleriyle orantılı olarak hesaplanır.'),
  ('Bir merdiven duvara dayanmışken yerle yaptığı açı artırılırsa merdivenin duvarda ulaştığı yükseklik nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce artar sonra azalır'], 'Yükseklik L·sin α\'dır; α dar açı aralığında arttıkça sinüs de artar.'),
  ('Büyüklükleri 3 ve 5 birim olan iki vektör arasındaki açı 60°\'dir. Bileşke vektörün büyüklüğü kaçtır?', '7', ['8', '√19', '√34'], '|R|² = 9 + 25 + 2·3·5·cos 60° = 34 + 15 = 49 ⇒ |R| = 7.'),
  ('Bir ikizkenar üçgende tepe açısı 2α, eşit kenarlar 1 birimdir. Taban uzunluğu α cinsinden hangisidir?', '2 sin α', ['sin 2α', '2 cos α', '2 sin α·cos α'], 'Tepe açıortayı tabanı ikiye böler; her yarı 1·sin α olduğundan taban 2 sin α.'),
  ('cos 2x = 7/25 ve x dar açı ise tan x kaçtır?', '3/4', ['4/3', '7/24', '24/7'], 'cos 2x = (1 − t²)/(1 + t²) = 7/25 ⇒ 25 − 25t² = 7 + 7t² ⇒ t² = 18/32 = 9/16 ⇒ t = 3/4.'),
  ('tan 15° + tan 30° + tan 15°·tan 30° toplamı kaçtır?', '1', ['√3', '2 − √3', '0'], 'a + b = 45° iken tan a + tan b = 1 − tan a tan b olduğundan ifade 1\'e eşittir.'),
  ('Sinüs ile kosinüsün çarpımı olan y = sin x·cos x, grafiğini hangi en küçük pozitif aralıkla yineler?', 'π', ['2π', 'π/2', '4π'], 'sin x cos x = (sin 2x)/2 olduğundan periyot 2π/2 = π\'dir.'),
  ('Yarım açının tanjantı ile sinüsün toplamından oluşan tan(x/2) + sin x için en küçük pozitif periyot nedir?', '2π', ['π', '4π', 'π/2'], 'tan(x/2)\'nin periyodu 2π, sin x\'in periyodu 2π; ortak en küçük periyot 2π.'),
  ('sec x + tan x = 3 ise sec x − tan x kaçtır?', '1/3', ['3', '−3', '1'], '(sec x + tan x)(sec x − tan x) = sec²x − tan²x = 1 olduğundan fark 1/3\'tür.'),
  ('Sekant ile tanjantın toplamının 3 olduğu bir açıda, önce farklarını bulup ardından kosinüsü hesaplayınız.', '3/5', ['4/5', '5/3', '1/3'], 'sec x − tan x = 1/3; toplanırsa 2 sec x = 10/3 ⇒ sec x = 5/3 ⇒ cos x = 3/5.'),
  ('Yönlü açılarda başlangıç kenarı ile bitiş kenarı aynı olan iki açı için hangisi kesinlikle aynıdır?', 'Trigonometrik değerleri', ['Ölçüleri', 'Dönme yönleri', 'Tur sayıları'], 'Aynı bitiş kenarı birim çemberde aynı noktayı verir; sinüs, kosinüs ve diğer değerler eşit olur.'),
  ('arcsin x = π/6 eşitliğini sağlayan x için arccos x kaç radyandır?', 'π/3', ['π/6', '2π/3', '5π/6'], 'x = 1/2\'dir ve arccos(1/2) = π/3; ayrıca arcsin x + arccos x = π/2\'den de bulunur.'),
  ('Kosinüsü 1/3 olan esas açının sinüsünü, yani sin(arccos(1/3)) değerini, işaretine dikkat ederek bulunuz.', '2√2/3', ['√2/3', '1/3', '−2√2/3'], 'θ ∈ [0, π] ve cos θ = 1/3 ⇒ sin θ = √(1 − 1/9) = √8/3 = 2√2/3 (sin θ ≥ 0).'),
  ('Bir salıncağın yatayla yaptığı açı θ(t) = (π/6)·sin(2t) ile veriliyor. θ = π/12 olduğu ilk pozitif t anı kaçtır?', 'π/12', ['π/6', 'π/24', '5π/12'], 'sin 2t = 1/2 ⇒ 2t = π/6 ⇒ t = π/12 (ilk pozitif çözüm).'),
  ('Bir açının tanjantı √3/3 ve açı üçüncü bölgede ise açı kaç derecedir (0° ile 360° arasında)?', '210°', ['30°', '150°', '−150°'], 'Referans açı 30°\'dir; üçüncü bölgede 180° + 30° = 210° olur.'),
  ('cos x = cos(x + π/2) eşitliğini sağlayan [0, 2π) aralığındaki x değerleri hangileridir?', '3π/4 ve 7π/4', ['π/4 ve 5π/4', 'π/2 ve 3π/2', 'π/4 ve 3π/4'], 'cos(x + π/2) = −sin x ⇒ cos x = −sin x ⇒ tan x = −1 ⇒ 3π/4, 7π/4.'),
  ('sin 2x = cos x denkleminin [0, 2π) aralığında kaç kökü vardır?', '4', ['2', '3', 'Sonsuz'], 'cos x(2 sin x − 1) = 0 ⇒ cos x = 0 (π/2, 3π/2) veya sin x = 1/2 (π/6, 5π/6); dört kök.'),
  ('ABC üçgeninde cos A·cos B > sin A·sin B ise C açısı için ne söylenebilir?', 'C geniş açıdır', ['C dar açıdır', 'C dik açıdır', 'C açısı A + B\'ye eşittir'], 'cos(A + B) > 0 ⇒ A + B < 90° ⇒ C > 90°.'),
  ('Bir eşkenar üçgenin bir köşesinden çizilen yükseklik ile aynı köşeden çıkan kenarlardan biri arasındaki açının tanjantı kaçtır?', '√3/3', ['√3', '1/2', '2√3/3'], 'Yükseklik tepe açısını ikiye böler ve kenarla 30°\'lik açı yapar; tan 30° = √3/3.'),
  ('0°\'den 180°\'ye kadar 60°\'lik adımlarla alınan açıların kosinüsleri toplanırsa (cos 0° + cos 60° + cos 120° + cos 180°) ne bulunur?', '0', ['1', '−1', '1/2'], 'Değerler 1, 1/2, −1/2 ve −1 olup toplamları sıfırdır.'),
  ('y = tan x eğrisi x eksenini hangi noktalarda keser (k ∈ ℤ)?', 'x = kπ', ['x = π/2 + kπ', 'x = 2kπ + π/4', 'x = kπ/2'], 'tan x = 0 ancak sin x = 0 iken olur; bu noktalar π\'nin tam katlarıdır. π/2 + kπ ise asimptotlardır.'),
  ('Üç kat açılı sin 3x/sin x ile cos 3x/cos x oranlarının farkı, tanımlı olduğu her x için sabittir. Bu sabit nedir?', '2', ['1', '3', '2√2'], 'Payda eşitlenirse pay sin 3x cos x − cos 3x sin x = sin 2x; sin 2x/(sin x cos x) = 2.'),
  ('İki kat açının sinüsünün pozitif olduğu açılar bir tam tur içinde hangi aralıkları oluşturur?', '(0, π/2) ∪ (π, 3π/2)', ['(0, π)', '(π/2, π) ∪ (3π/2, 2π)', '(0, π/4) ∪ (π, 5π/4)'], '2x ∈ (0, 2π) ∪ (2π, 3π) aralığında sinüs pozitiftir; bölünce x ∈ (0, π/2) ∪ (π, 3π/2).'),
  ('Bir sarkacın açısal konumu θ(t) = 0,1·cos(2πt) radyan ile veriliyor (t saniye). Sarkaç 1 dakikada kaç tam salınım yapar?', '60', ['120', '30', '6'], 'Periyot 2π/(2π) = 1 saniyedir; 60 saniyede 60 tam salınım olur.'),
  ('Birim çember üzerindeki bir P noktası (1, 0)\'dan başlayarak pozitif yönde 2π/3 radyanlık yay boyunca ilerliyor. P\'nin yeni koordinatları hangisidir?', '(−1/2, √3/2)', ['(1/2, √3/2)', '(−√3/2, 1/2)', '(−1/2, −√3/2)'], 'Koordinatlar (cos 2π/3, sin 2π/3) = (−1/2, √3/2) olur.'),
  ('tan 3x ifadesinin tan x = t cinsinden açılımı hangisidir?', '(3t − t³)/(1 − 3t²)', ['(3t + t³)/(1 + 3t²)', '(3t − t³)/(1 + 3t²)', '(3t − t³)/(1 − 3t²)²'], 'tan(2x + x) açılımında tan 2x = 2t/(1 − t²) yazılıp sadeleştirilirse (3t − t³)/(1 − 3t²) bulunur.'),
  ('Farkı çarpıma dönüştürerek sin 3x = sin x eşitliğini sağlayan ve uçlar dahil 0 ile π arasında bulunan açıları sayınız.', '4', ['3', '2', 'Sonsuz'], '2 cos 2x sin x = 0 ⇒ sin x = 0 (0, π) veya cos 2x = 0 (π/4, 3π/4); dört çözüm.'),
  ('Sinüs değerlerini 3,75°\'lik aralıklarla veren bir tabloyu MS 499 dolaylarında yazdığı eserine koyan Hint matematikçisi kimdir?', 'Aryabhata', ['Brahmagupta', 'Bhaskara II', 'Ramanujan'], 'Aryabhata\'nın Aryabhatiya adlı eserinde 24 değerlik bir sinüs farkları tablosu bulunur.'),
  ('"Radyan" teriminin yaygınlaşmasından önce bu açı ölçüsünün matematikte doğal olarak ortaya çıkmasının nedeni nedir?', 'Analiz formüllerinin bu birimle sadeleşmesi', ['Babillilerin 60\'lık sistemi', 'Gökbilimdeki derece tabloları', 'Saat kadranının on iki eşit parçaya bölünmesi'], 'Örneğin sin x\'in türevinin cos x olması ve sin x ≈ x yaklaşımı yalnız radyan ölçüsünde geçerlidir.'),
  ('Kareli terimlerden oluşan 2sin²x + 3cos²x ifadesi, temel özdeşlik yardımıyla hangi değerler arasında kalır?', '[2, 3]', ['[0, 5]', '[2, 5]', '[−1, 3]'], 'y = 2 + cos²x ve cos²x ∈ [0, 1] olduğundan y ∈ [2, 3].'),
  ('Işık kırılma indisi √2 olan bir ortamdan 45°\'lik gelme açısıyla kırılma indisi 2 olan bir ortama geçiyor. Snell yasasına (n₁·sin θ₁ = n₂·sin θ₂) göre kırılma açısı kaç derecedir?', '30°', ['45°', '60°', '22,5°'], '√2·sin 45° = 1 = 2·sin θ₂ ⇒ sin θ₂ = 1/2 ⇒ θ₂ = 30°.'),
  ('Hava direnci ihmal edildiğinde eğik atışta yatay menzil R = v²·sin 2θ / g ile verilir. Aynı hızla atılan bir cisim için menzil hangi atış açısında en büyüktür?', '45°', ['30°', '60°', '22,5°'], 'sin 2θ en çok 1 olur; bu da 2θ = 90°, yani θ = 45° için gerçekleşir.'),
  ('Taban kenarı 6 cm, yüksekliği 3√2 cm olan kare dik piramitte yan ayrıtın taban düzlemiyle yaptığı açı kaç derecedir?', '45°', ['30°', '60°', '54,7°'], 'Taban merkezinden köşeye uzaklık köşegenin yarısı 3√2\'dir; tan = 3√2/3√2 = 1 ⇒ 45°.'),
  ('Taban yarıçapı 3 cm, yüksekliği 4 cm olan dik koninin ana doğrusu ile ekseni arasındaki açının sinüsü kaçtır?', '3/5', ['4/5', '3/4', '4/3'], 'Ana doğru 5 cm\'dir; eksenle yapılan açının karşısında yarıçap bulunur: sin = 3/5.'),
  ('Tanjant teoremine göre ABC üçgeninde (a − b)/(a + b) oranı hangi ifadeye eşittir?', 'tan((A − B)/2) / tan((A + B)/2)', ['tan(A − B) / tan(A + B)', 'sin(A − B) / sin(A + B)', '2·tan((A − B)/2) / tan((A + B)/2)'], 'Sinüs teoremi ve toplamı çarpıma dönüştürme formülleri birleştirilince bu oran elde edilir.'),
  ('Eşkenar bir üçgende tan A·tan B·tan C çarpımı kaçtır?', '3√3', ['√3', '3', '√3/3'], 'tan 60° = √3 olduğundan çarpım (√3)³ = 3√3\'tür; bu değer tan A + tan B + tan C toplamına da eşittir.'),
  ('Kutupsal koordinatlarda (−r, θ) ile gösterilen nokta (r > 0) aşağıdakilerden hangisiyle aynı noktadır?', '(r, θ + π)', ['(r, −θ)', '(r, π − θ)', '(−r, θ + π)'], 'Negatif r, θ doğrultusunun tersine r birim gitmek demektir; bu da θ + π doğrultusunda r birimdir.'),
  ('x > 0 için arctan x + arctan(1/x) toplamı hangi sabite eşittir?', 'π/2', ['π/4', 'π', '3π/4'], 'arctan x = θ ise tan(π/2 − θ) = 1/x olur ve π/2 − θ ∈ (0, π/2); dolayısıyla toplam π/2\'dir.'),
  ('y = 2 sin 3x fonksiyonu [0, 2π) aralığında en büyük değerini kaç kez alır?', '3', ['2', '6', '1/3'], '3x = π/2 + 2kπ ⇒ x = π/6 + 2kπ/3; aralıkta π/6, 5π/6 ve 3π/2 olmak üzere üç değer vardır.'),
  ('y = sin⁴x + cos⁴x ifadesinin görüntü kümesi hangisidir?', '[1/2, 1]', ['[0, 1]', '[1/4, 1]', '[1/2, √2/2 + 1]'], 'sin⁴x + cos⁴x = 1 − (sin²2x)/2 ve sin²2x ∈ [0, 1] olduğundan değerler 1/2 ile 1 arasındadır.'),
  ('sin x + √3 cos x toplamını tek bir sinüs terimine dönüştürerek ulaşabileceği en alt değeri bulunuz.', '−2', ['−1 − √3', '−√3', '−4'], 'İfade 2 sin(x + π/3) biçimindedir; en küçük değer −2\'dir.'),
  ('Paydaki 1\'i tan 45° olarak düşünerek (1 + tan x)/(1 − tan x) oranını tek bir tanjant olarak yazınız.', 'tan(45° + x)', ['tan(45° − x)', 'cot(45° + x)', 'tan 2x·tan(45° + x)'], 'tan 45° = 1 yazılırsa ifade (tan 45° + tan x)/(1 − tan 45°·tan x) = tan(45° + x) olur.'),
  ('cos x + sin x·tan x toplamı sadeleştirildiğinde hangi fonksiyon elde edilir?', 'sec x', ['csc x', 'cos x·tan x', '1 + sin x'], 'sin x·tan x = sin²x/cos x; toplam (cos²x + sin²x)/cos x = 1/cos x = sec x.'),
  ('Kosinüsün iki kat açısını sinüse çevirerek sin x = cos 2x eşitliğini bir tam tur içinde sağlayan açıları belirleyiniz.', 'π/6, 5π/6 ve 3π/2', ['π/6 ve 5π/6', 'π/2, 7π/6 ve 11π/6', 'π/6, π/2 ve 5π/6'], 'cos 2x = 1 − 2sin²x ⇒ 2sin²x + sin x − 1 = 0 ⇒ sin x = 1/2 veya sin x = −1.'),
  ('tan x = cot x denkleminin genel çözümü hangisidir (k ∈ ℤ)?', 'x = π/4 + kπ/2', ['x = π/4 + kπ', 'x = π/4 + 2kπ', 'x = π/4 + kπ/4'], 'tan²x = 1 ⇒ tan x = ±1 ⇒ x = ±π/4 + kπ; bunlar birlikte π/4 + kπ/2 biçiminde yazılır.'),
  ('Tanjantı −√3 olan bütün açılar, k tam sayı olmak üzere tek bir ifadeyle nasıl yazılır?', 'x = 2π/3 + kπ', ['x = π/3 + kπ', 'x = −π/6 + kπ', 'x = 2π/3 + 2kπ'], 'tan(2π/3) = −√3 ve tanjantın periyodu π olduğundan x = 2π/3 + kπ.'),
  ('Birim çemberde θ ve π − θ açılarına karşılık gelen noktalar birbirinin neyine göre simetriğidir?', 'y eksenine', ['x eksenine', 'Orijine', 'y = x doğrusuna'], '(cos θ, sin θ) noktası (−cos θ, sin θ) olur; apsisin işareti değiştiğinden y eksenine göre simetriktir.'),
  ('Denizcilikte kerteriz açısı kuzeyden saat yönünde ölçülür. Kerterizi 210° olan bir doğrultu hangi yöndür?', 'Güneyden 30° batı', ['Güneyden 30° doğu', 'Batıdan 30° kuzey', 'Kuzeyden 30° batı'], '180° güneydir; 30° daha saat yönünde dönmek güneyden batıya doğru 30° sapma demektir.'),
  ('tan x·tan(60° − x)·tan(60° + x) = tan 3x özdeşliğine göre tan 20°·tan 40°·tan 80° çarpımı kaçtır?', '√3', ['√3/3', '1', '3'], 'x = 20° alınırsa 60° − x = 40°, 60° + x = 80° olur; çarpım tan 60° = √3 eder.'),
  ('Bir üçgende (a − b)/(a + b) = tan((A − B)/2)/tan((A + B)/2) eşitliği hangi adla bilinir?', 'Tanjant teoremi', ['Kosinüs teoremi', 'Mollweide sinüs kuralı', 'Projeksiyon teoremi'], 'Kenar farkı ile toplamının oranını açı farkı ve toplamının yarısının tanjantlarına bağlayan bağıntı tanjant teoremidir.'),
];
